import 'server-only'

/**
 * Sends a page-view event to the configured analytics collector.
 *
 * Set ANALYTICS_ENDPOINT to the collector's event-ingestion URL. An optional
 * ANALYTICS_API_KEY is sent as a bearer token.
 */
export async function logPageView(path: string): Promise<void> {
  const endpoint = process.env.ANALYTICS_ENDPOINT

  if (!endpoint) {
    console.warn('Page view skipped: ANALYTICS_ENDPOINT is not configured')
    return
  }

  const apiKey = process.env.ANALYTICS_API_KEY
  const response = await fetch(endpoint, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      ...(apiKey ? { authorization: `Bearer ${apiKey}` } : {}),
    },
    body: JSON.stringify({
      event: 'page_view',
      path,
      occurredAt: new Date().toISOString(),
    }),
  })

  if (!response.ok) {
    throw new Error(`Analytics request failed with status ${response.status}`)
  }
}
